    "ov.fileLayer": ["标注图层.png", "標註圖層.png", "annotation-layer.png", "注釈レイヤー.png", "주석-레이어.png", "anmerkungsebene.png", "calque-annotation.png", "capa-anotacion.png"],
    "ov.tooBigSave": ["存档超过 10 MiB 限制，请先精简标注", "存檔超過 10 MiB 限制，請先精簡標註", "The file exceeds the 10 MiB limit. Remove some annotations first.", "ファイルが 10 MiB の上限を超えています。注釈を減らしてください", "파일이 10 MiB 한도를 넘습니다. 주석을 줄이세요", "Die Datei überschreitet 10 MiB. Bitte zuerst Anmerkungen reduzieren.", "Le fichier dépasse la limite de 10 Mio. Réduisez d'abord les annotations.", "El archivo supera el límite de 10 MiB. Reduce primero las anotaciones."],
    "ov.tooBigOpen": ["存档超过 10 MiB，未导入任何内容", "存檔超過 10 MiB，未匯入任何內容", "The file exceeds 10 MiB; nothing was imported", "ファイルが 10 MiB を超えているため、何も読み込みませんでした", "파일이 10 MiB를 넘어 아무것도 가져오지 않았습니다", "Die Datei ist größer als 10 MiB; nichts wurde importiert", "Le fichier dépasse 10 Mio ; rien n'a été importé", "El archivo supera 10 MiB; no se importó nada"],
    "ov.openConfirm": ["打开存档会替换当前屏幕标注；iPad 和共享白板不受影响。继续？", "開啟存檔會取代目前螢幕標註；iPad 和共享白板不受影響。繼續？", "Opening the file replaces the current screen annotations; the iPad and the shared whiteboard are not affected. Continue?", "ファイルを開くと現在の画面注釈が置き換えられます（iPad と共有ホワイトボードには影響しません）。続けますか？", "파일을 열면 현재 화면 주석이 대체됩니다(iPad와 공유 화이트보드에는 영향 없음). 계속할까요?", "Das Öffnen ersetzt die aktuellen Bildschirmanmerkungen; iPad und gemeinsames Whiteboard bleiben unverändert. Fortfahren?", "Ouvrir le fichier remplace les annotations actuelles ; l'iPad et le tableau partagé ne sont pas modifiés. Continuer ?", "Abrir el archivo reemplaza las anotaciones actuales; el iPad y la pizarra compartida no cambian. ¿Continuar?"],
    "ov.openDlgTitle": ["打开存档", "開啟存檔", "Open file", "ファイルを開く", "파일 열기", "Datei öffnen", "Ouvrir le fichier", "Abrir archivo"],
    "ov.notSent": ["连接已断开，未发送存档", "連線已中斷，未傳送存檔", "Disconnected; the file was not sent", "接続が切れたため、ファイルは送信されていません", "연결이 끊겨 파일을 보내지 않았습니다", "Verbindung getrennt; die Datei wurde nicht gesendet", "Déconnecté ; le fichier n'a pas été envoyé", "Desconectado; no se envió el archivo"],
    "ov.noAck": ["未收到导入确认，请核对当前标注后重试", "未收到匯入確認，請核對目前標註後重試", "No import confirmation received. Check the current annotations and try again.", "読み込みの確認が届きませんでした。現在の注釈を確認してからもう一度お試しください", "가져오기 확인을 받지 못했습니다. 현재 주석을 확인한 뒤 다시 시도하세요", "Keine Importbestätigung erhalten. Anmerkungen prüfen und erneut versuchen.", "Aucune confirmation d'import reçue. Vérifiez les annotations et réessayez.", "No se recibió confirmación de importación. Revisa las anotaciones y vuelve a intentarlo."],
    "ov.initFail": ["标注层初始化失败：{e}", "標註層初始化失敗：{e}", "Annotation layer failed to start: {e}", "注釈レイヤーの初期化に失敗しました：{e}", "주석 레이어 초기화 실패: {e}", "Anmerkungsebene konnte nicht starten: {e}", "Échec de l'initialisation du calque : {e}", "No se pudo iniciar la capa de anotación: {e}"],

    // ---------- 容量与存档校验 ----------
    "usage.full": ["白板已满，请先存档再清屏，或撤销后继续", "白板已滿，請先存檔再清除，或復原後繼續", "The whiteboard is full. Save it and clear it, or undo to continue.", "ホワイトボードがいっぱいです。保存して消去するか、元に戻してから続けてください", "화이트보드가 가득 찼습니다. 저장 후 지우거나 실행 취소한 뒤 계속하세요", "Das Whiteboard ist voll. Speichern und leeren oder rückgängig machen, um fortzufahren.", "Le tableau est plein. Enregistrez-le puis effacez-le, ou annulez pour continuer.", "La pizarra está llena. Guárdala y bórrala, o deshaz para continuar."],
    "usage.critical": ["白板容量已达 95%，请尽快存档后清屏", "白板容量已達 95%，請盡快存檔後清除", "The whiteboard is 95% full. Save and clear it soon.", "ホワイトボードの容量が 95% に達しました。早めに保存して消去してください", "화이트보드 용량이 95%에 도달했습니다. 곧 저장하고 지우세요", "Das Whiteboard ist zu 95 % voll. Bitte bald speichern und leeren.", "Le tableau est plein à 95 %. Enregistrez-le et effacez-le bientôt.", "La pizarra está al 95 %. Guárdala y bórrala pronto."],
    "usage.warning": ["白板接近容量上限（80%），建议存档后清屏", "白板接近容量上限（80%），建議存檔後清除", "The whiteboard is nearly full (80%). Consider saving and clearing it.", "ホワイトボードの容量が上限に近づいています（80%）。保存して消去することをおすすめします", "화이트보드 용량이 거의 찼습니다(80%). 저장 후 지우는 것을 권장합니다", "Das Whiteboard ist fast voll (80 %). Speichern und leeren wird empfohlen.", "Le tableau est presque plein (80 %). Pensez à l'enregistrer et l'effacer.", "La pizarra está casi llena (80 %). Conviene guardarla y borrarla."],
    "arc.version": ["存档格式或版本不支持（支持 v1 / v2）", "存檔格式或版本不支援（支援 v1 / v2）", "Unsupported file format or version (v1 / v2 supported)", "対応していないファイル形式またはバージョンです（v1 / v2 に対応）", "지원하지 않는 파일 형식 또는 버전입니다(v1 / v2 지원)", "Nicht unterstütztes Dateiformat oder Version (v1 / v2 werden unterstützt)", "Format ou version de fichier non pris en charge (v1 / v2 pris en charge)", "Formato o versión de archivo no compatible (se admiten v1 / v2)"],
    "arc.notOverlay": ["此文件不是屏幕标注存档", "此檔案不是螢幕標註存檔", "This file is not a screen annotation file", "このファイルは画面注釈ファイルではありません", "이 파일은 화면 주석 파일이 아닙니다", "Diese Datei ist keine Bildschirm-Anmerkungsdatei", "Ce fichier n'est pas un fichier d'annotations d'écran", "Este archivo no es de anotaciones de pantalla"],
    "arc.tooManyStrokes": ["存档超过 2000 笔限制", "存檔超過 2000 筆限制", "The file exceeds the 2,000-stroke limit", "ファイルが 2000 ストロークの上限を超えています", "파일이 2,000획 한도를 넘습니다", "Die Datei überschreitet das Limit von 2.000 Strichen", "Le fichier dépasse la limite de 2 000 traits", "El archivo supera el límite de 2000 trazos"],
