    "diag.send": ["发送书写诊断到电脑", "傳送書寫診斷到電腦", "Send writing diagnostics to PC", "書き込み診断を PC に送信", "필기 진단을 PC로 보내기", "Schreibdiagnose an PC senden", "Envoyer le diagnostic au PC", "Enviar diagnóstico al PC"],
