    "tray.toggle": ["切换 穿透/绘制", "切換 穿透/繪製", "Toggle click-through / draw", "クリックスルー／描画を切り替え", "클릭 통과/그리기 전환", "Durchklicken / Zeichnen umschalten", "Basculer clic traversant / dessin", "Alternar clic a través / dibujo"],
    "tray.closeOverlay": ["关闭标注层", "關閉標註層", "Close annotation layer", "注釈レイヤーを閉じる", "주석 레이어 닫기", "Anmerkungsebene schließen", "Fermer le calque d'annotation", "Cerrar capa de anotación"],
